sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float progress;
uniform float noiseScale;
uniform float complexity;
uniform float evolve;
uniform float edgeWidth;
uniform float softness;
layout(color) uniform half4 edgeColor;
uniform float edgeGlow;
uniform float biasAngle;
uniform float directionBias;
uniform float reverse;
uniform float opacity;
float4 tex(float2 p) {
    return float4(image.eval(clamp(p, float2(0.0), size)));
}
float3 unp(float4 c) {
    return c.rgb / max(c.a, 0.0001);
}
half4 fin(float4 o, float4 r, float op) {
    return half4(mix(o, r, saturate(op)));
}
float hash21(float2 p) {
    return fract(sin(dot(p, float2(127.1, 311.7))) * 43758.5453);
}
float vnoise(float2 p) {
    float2 i = floor(p);
    float2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    float a = hash21(i);
    float b = hash21(i + float2(1.0, 0.0));
    float c = hash21(i + float2(0.0, 1.0));
    float d = hash21(i + float2(1.0, 1.0));
    return mix(mix(a, b, f.x), mix(c, d, f.x), f.y);
}
float fbm(float2 p, float oct, float rough) {
    float v = 0.0;
    float a = 0.5;
    float norm = 0.0;
    for (int i = 0; i < 6; i++) {
        if (float(i) >= oct) break;
        v += a * vnoise(p);
        norm += a;
        p = p * 2.03 + float2(11.7, 5.3);
        a *= rough;
    }
    return v / max(norm, 0.0001);
}
half4 main(float2 coord) {
    float4 c = tex(coord);
    float3 s = unp(c);
    float n = fbm(coord / max(noiseScale, 1.0) + time * evolve, complexity, 0.5);
    float g = dot(coord / size - float2(0.5), float2(cos(radians(biasAngle)), sin(radians(biasAngle)))) + 0.5;
    n = mix(n, 1.0 - g, directionBias);
    float t = reverse > 0.5 ? 1.0 - n : n;
    float th = mix(-edgeWidth - softness, 1.0 + softness, progress);
    float keep = smoothstep(th - softness, th + softness + 0.0001, t);
    float edge = smoothstep(th - softness, th + softness + 0.0001, t) * (1.0 - smoothstep(th + edgeWidth - softness, th + edgeWidth + softness + 0.0001, t));
    float3 o = s + float3(edgeColor.rgb) * edge * edgeGlow;
    float4 r = float4(max(o, float3(0.0)) * c.a * keep, c.a * keep);
    return fin(c, r, opacity);
}
